package lightly.monitor.data
import org.json.JSONArray
import org.json.JSONObject

data class EasyTierConfig(val instanceName:String,val networkName:String,val networkSecret:String?=null,val ipv4:String?=null,val dhcp:Boolean=false,val peers:List<String> = emptyList(),val listeners:List<String> = emptyList(),val socks5Port:Int?=null,val enableP2p:Boolean=true,val hostname:String?=null){
 fun toToml():String=buildString{appendLine("instance_name = \"$instanceName\"");appendLine("hostname = \"${hostname?.takeIf{it.isNotBlank()}?:instanceName}\"");if(dhcp)appendLine("dhcp = true") else if(!ipv4.isNullOrEmpty())appendLine("ipv4 = \"$ipv4\"");peers.forEach{appendLine();appendLine("[[peer]]");appendLine("uri = \"$it\"")};if(listeners.isNotEmpty()){appendLine();appendLine("listeners = [${listeners.joinToString(", "){"\"$it\""}}]")};if(socks5Port!=null){appendLine();appendLine("socks5_proxy = \"socks5://127.0.0.1:$socks5Port\"")};appendLine();appendLine("[network_identity]");appendLine("network_name = \"$networkName\"");appendLine("network_secret = \"${networkSecret?:""}\"");appendLine();appendLine("[flags]");appendLine("disable_p2p = ${!enableP2p}")}
 fun toJson()=JSONObject().put("instanceName",instanceName).put("networkName",networkName).put("networkSecret",networkSecret).put("ipv4",ipv4).put("dhcp",dhcp).put("peers",JSONArray(peers)).put("listeners",JSONArray(listeners)).put("socks5Port",socks5Port).put("enableP2p",enableP2p).put("hostname",hostname)
 companion object{fun default()=EasyTierConfig("lightly_monitor","default_network","","",false, hostname="lightly_monitor"); fun fromJson(j:JSONObject)=EasyTierConfig(j.optString("instanceName"),j.optString("networkName"),j.optString("networkSecret").takeIf{it.isNotEmpty()},j.optString("ipv4").takeIf{it.isNotEmpty()},j.optBoolean("dhcp",false),j.optJSONArray("peers").strings(),j.optJSONArray("listeners").strings(),if(j.has("socks5Port")&&!j.isNull("socks5Port"))j.optInt("socks5Port") else null,j.optBoolean("enableP2p",true),j.optString("hostname").takeIf{it.isNotEmpty()})}
}
private fun JSONArray?.strings():List<String>{if(this==null)return emptyList();return (0 until length()).mapNotNull{optString(it).takeIf{v->v.isNotBlank()}}}
